import asyncio
from fastmcp import FastMCP


async def main():
    # Create math sub-server with tools
    math_server = FastMCP("math_service")

    @math_server.call_tool
    def add(a: float, b: float) -> float:
        """Add two numbers."""
        return a + b

    @math_server.call_tool
    def subtract(a: float, b: float) -> float:
        """Subtract two numbers."""
        return a - b

    @math_server.call_tool
    def multiply(a: float, b: float) -> float:
        """Multiply two numbers."""
        return a * b

    @math_server.call_tool
    def divide(a: float, b: float) -> float:
        """Divide two numbers."""
        if b == 0:
            raise ValueError("Cannot divide by zero")
        return a / b

    # Create main server
    main_server = FastMCP("main_server")

    # Mount math sub-server under "math" namespace
    main_server.mount(math_server, namespace="math")

    # Run the main server
    await main_server.run()


if __name__ == "__main__":
    asyncio.run(main())
